-- @name: coverage kirby copy
-- @gameplay: true
-- @rollback_safe: false
-- Generated by gen_pads.py; do not edit.
-- P1 Kirby (human) runs at the idle CPUs, inhales (hold B), swallows (Down), uses the copied B, repeats.
local FRAMES = 2400
local n = 0
local seq = {
  {140, 0, 0, 0},
  {25, 0, 100, 0}, {70, 'B', 0, 0}, {6, 0, 0, -127}, {30, 0, 0, 0},         -- inhale + swallow
  {8, 'B', 0, 0}, {30, 0, 0, 0}, {8, 'B', 100, 0}, {40, 0, 0, 0}, {8, 'B', 0, 127}, {40, 0, 0, 0},
  {8, 'B', 0, -127}, {40, 0, 0, 0}, {4, 'X', 100, 0}, {30, 0, 100, 0},
  {70, 'B', 0, 0}, {6, 0, 0, -127}, {30, 0, 0, 0}, {8, 'B', 0, 0}, {40, 0, 0, 0},
  {25, 0, 100, 0}, {70, 'B', 0, 0}, {6, 0, 0, -127}, {40, 0, 0, 0}, {10, 'A', 0, 0},
}
local total = 0
for _, p in ipairs(seq) do total = total + p[1] end
local function at(frame)
  frame = frame % total
  for _, p in ipairs(seq) do
    if frame < p[1] then return {buttons = p[2], x = p[3], y = p[4]} end
    frame = frame - p[1]
  end
end
function on_frame_pre()
    local m = gd.match()
    if not (m and m.active) then return end
    n = n + 1
    gd.input(1, at(n), 2)
    if n == FRAMES then
        gd.log("COVERAGE quit at frame " .. n)
        gd.quit()
    end
end
